import sys, zlib
d = bytes.fromhex(sys.stdin.read().strip())
N = {0: "None", 1: "CRC32", 4: "CRC64", 10: "SHA-256"}
if d[:6] != b"\xfd7zXZ\x00":
    print("BAD MAGIC")
elif zlib.crc32(d[6:8]) != int.from_bytes(d[8:12], "little"):
    print("BAD CRC")
else:
    t = d[7] & 15
    print("OK " + N[t] if t in N else "OK type=%d" % t)

